class Solution {
    public double myPow(double x, int n) {
        long exponent = n;
        if (exponent < 0) {
            x = 1.0 / x;
            exponent = -exponent;
        }

        double answer = 1.0;
        while (exponent > 0) {
            if ((exponent & 1L) == 1L) {
                answer *= x;
            }
            x *= x;
            exponent >>= 1;
        }
        return answer;
    }
}

class Solution {
    public double myPow(double x, int n) {
        long exponent = n;
        if (exponent < 0) {
            return 1.0 / power(x, -exponent);
        }
        return power(x, exponent);
    }

    private double power(double base, long exponent) {
        if (exponent == 0) {
            return 1.0;
        }
        double half = power(base, exponent / 2);
        double squared = half * half;
        return exponent % 2 == 0 ? squared : squared * base;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public double myPow(double x, int n) {
        long exponent = n;
        boolean negative = exponent < 0;
        if (negative) {
            exponent = -exponent;
        }

        List<Double> powers = new ArrayList<>();
        double current = x;
        for (long value = exponent; value > 0; value >>= 1) {
            powers.add(current);
            current *= current;
        }

        double answer = 1.0;
        int bit = 0;
        while (exponent > 0) {
            if ((exponent & 1L) == 1L) {
                answer *= powers.get(bit);
            }
            bit++;
            exponent >>= 1;
        }
        return negative ? 1.0 / answer : answer;
    }
}

class Solution {
    public double myPow(double x, int n) {
        long exponent = n;
        boolean negative = exponent < 0;
        if (negative) {
            exponent = -exponent;
        }
        if (exponent == 0) {
            return 1.0;
        }

        int highestBit = 63 - Long.numberOfLeadingZeros(exponent);
        double answer = 1.0;
        for (int bit = highestBit; bit >= 0; bit--) {
            answer *= answer;
            if (((exponent >> bit) & 1L) == 1L) {
                answer *= x;
            }
        }
        return negative ? 1.0 / answer : answer;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public double myPow(double x, int n) {
        long exponent = n;
        boolean negative = exponent < 0;
        if (negative) {
            exponent = -exponent;
        }

        Deque<Long> stack = new ArrayDeque<>();
        while (exponent > 0) {
            stack.push(exponent);
            exponent /= 2;
        }

        double current = 1.0;
        while (!stack.isEmpty()) {
            long value = stack.pop();
            current *= current;
            if ((value & 1L) == 1L) {
                current *= x;
            }
        }
        return negative ? 1.0 / current : current;
    }
}
